        purpose: { pt: "Visualizar os 6 footswitches como ficarão no display e inspecionar o MIDI enviado.", en: "Visualize the 6 footswitches as they'll look on the display and inspect the MIDI sent.", es: "Visualizar los 6 footswitches como quedarán en la pantalla e inspeccionar el MIDI enviado." },
        howto: [
          { pt: "No desktop, a grade 2×3 ao lado mostra o tile de cada SW (ícone/sigla/LED) — tocar num tile seleciona o SW para edição.", en: "On desktop, the 2×3 grid alongside shows each SW's tile (icon/tag/LED) — tapping a tile selects the SW for editing.", es: "En escritorio, la cuadrícula 2×3 al lado muestra el tile de cada SW (icono/sigla/LED) — tocar un tile selecciona el SW para edición." },
          { pt: "O <strong>Monitor MIDI</strong> (ícone no cabeçalho) abre um modal com o snapshot do preset e o último disparo de SW.", en: "The <strong>MIDI Monitor</strong> (icon in the header) opens a modal with the preset's snapshot and the last SW trigger.", es: "El <strong>Monitor MIDI</strong> (icono en el encabezado) abre un modal con el snapshot del preset y el último disparo de SW." }
        ],
